(()=>{
 const original=document.currentScript;
 const next=document.createElement('script');
 const part1="";
 const cleanup=()=>{delete window.finishCircuitStudio15;next.remove()};
 window.finishCircuitStudio15=part2=>{cleanup();window.receive('15',part1+part2)};
 next.onerror=()=>{cleanup();original.dispatchEvent(new Event('error'))};
 next.src=new URL('15-part2.js',original.src).href;
 document.head.append(next);
})();